/* VB-MAPP: bảng phương hướng can thiệp theo mốc (điểm 0 đến 15) của từng kỹ năng */
const LVBS=[["YC","Yêu cầu"],["GT","Gán tên"],["NH","Nghe hiểu"],["GM","Nhận thức thị giác và ghép mẫu"],["CDL","Chơi độc lập"],["CXH","Hành vi xã hội và chơi xã hội"],["BC","Bắt chước vận động"],["PA","Phát âm"],["LN","Lời nói tự phát"],["FFC","Nghe phản hồi theo chức năng, đặc tính và chủng loại (LRFFC)"],["HT","Hội thoại"],["KNN","Kỹ năng nhóm"],["NP","Cấu trúc ngữ pháp"],["DOC","Đọc"],["VIET","Viết"],["TOAN","Toán"]];
const LVBD={"YC":{"0":"(1) xác định củng cố (2) lên mục tiêu dạy ngay (3) chọn hình thức (4) xem rào cản và giải quyết","1":"(1) giảm dần lời nhắc (2) tăng số lượng yêu cầu đơn lẻ, cụ thể, hay sử dụng","2":"(1) khái quát hóa (2) tăng tần suất yêu cầu (3) tăng số lượng (4) từ giảm nhắc đến không nhắc","3":"(1) tăng tần suất (2) tự phát yêu cầu nhiều hơn (3) khái quát hóa yêu cầu mới","4":"(1) tăng số lượng (2) tăng tần suất (3) tăng tự phát (4) khái quát hóa","5":"(1) bắt đầu yêu cầu vật không hiện hữu (2) phát triển cân bằng với Gán tên và Nghe hiểu","6":"(1) mở rộng nhiều yêu cầu đồ vật hiện hữu và không (2) Khái quát hóa yêu cầu đồ vật (3) Không nhắc nhở (4) Yêu cầu hành động của người khác","7":"(1) Thường xuyên và tự phát (2) Tăng số lượng yêu cầu (3) Dạy yêu cầu kết hợp động từ và danh","8":"(1) Khái quát hóa, tự phát, tăng số lượng và đa dạng yêu cầu (2) Bắt đầu dạy yêu cầu thông tin (3) Yêu cầu có đại từ, tính từ, trạng từ (4) Yêu cầu loại bỏ điều khó chịu","9":"(1) Tự phát yêu cầu (hiếm khi sắp xếp kích thích) (2) Yêu cầu mang tính khái quát hóa cao (3) Bắt đầu yêu cầu thông tin","10":"(1) Yêu cầu thông tin thường xuyên (2) Yêu cầu có nhiều thành phần của lời nói và từ 3 từ trở lên (3) Có sự củng cố khác biệt giữa yêu cầu cũ và yêu cầu mới","11":"(1) Tăng số lượng yêu cầu thông tin bằng câu hỏi Wh (2) Tăng tần suất (3) Khái quát nhiều người, người được hỏi cung cấp thông tin mở rộng với cấu trúc nhiều thành phần","12":"(1) mở rộng và khái quát hóa yêu cầu loại bỏ điều khó chịu những tình huống gây khó chịu (2) củng cố trong môi trường tự nhiên (3) thêm cử chỉ phi ngôn ngữ đi kèm với kiểu yêu cầu này (lắc đầu, xua tay, …)","13":"(1) yêu cầu trong tương tác xã hội (2) yêu cầu thu hút chú ý vào điều trẻ nói và hoạt động trẻ làm (3) bắt đầu dạy yêu cầu thông tin \"khi nào? Như thế nào? Tại sao?\"","14":"(1) Theo dõi tỷ mỉ để giảm kiểu yêu cầu người khác làm gì nếu trẻ biểu hiện thái quá \"hách dịch\" (2) Can thiệp nếu thấy xuất hiện hành vi yêu cầu lặp lại (3) Tiếp tục mở rộng và khái quát hóa yêu cầu kiểu này nếu phù hợp","15":"(1) yêu cầu được chú ý đến cảm xúc của mình (2) phát triển yêu cầu trong hội thoại"},"GT":{"0":"(1) đạt 2 điểm Phát âm và 1 điểm Yêu cầu thì lên mục tiêu dạy Gán tên (2) xem xét rào cản và giải quyết","1":"(1) tăng số lượng, tập trung vào vật 3D có tính củng cố, quen thuộc","2":"(1) gán tên hình ảnh (2) khái quát hóa gán tên với người, bối cảnh, thời gian","3":"(1) tăng số lượng gán tên (2) khái quát hóa sự vật được gán tên (3) giảm nhắc bằng lời \"đó là gì?\"","4":"(1) tăng số lương (2) tăng tần suất (3) tăng tự phát (4) khái quát hóa","5":"(1) bắt đầu gán tên hành động (2) phát triển cân bằng với Nghe hiểu","6":"(1)Tăng số lượng và củng cố (2) Khái quát hóa Gán tên danh từ (3) Phát triển cân bằng với Nghe hiểu (4) Thêm nhiều Gán tên động từ","7":"(1) Khái quát hóa Gán tên động từ (2) Tự phát Gán tên (3) Gán tên 2 thành phần (danh từ-danh từ, danh từ - động tự, động từ-danh từ)","8":"(1) Khái quát hóa, tự phát, tăng số lượng và đa dạng Gán tên (2) Gán tên 2 thành phần trong cấu trúc câu ý nghĩa: Đây là/đó là/ kia là/ có ...","9":"(1) Gán tên có nhiều thành phần của ngôn ngữ (tính từ, đại từ, trạng từ) và sử dụng cụm/câu 3 từ trở lên (2) Phát triển cân bằng với nghe hiểu: Phản ứng lại câu hỏi (3) Phát triển cân bằng với nội dung yêu cầu: Tự phát yêu cầu","10":"(1) Cân bằng với lĩnh vực khác (điều chỉnh trong suốt quá trình dạy) (2) Tăng quy mô từ vựng Gán tên (3) Diễn đạt trôi chảy (4) Khái quát trong môi trường tự nhiên","11":"(1) Tăng số lượng phản hồi kết hợp giữa Gán tên và Hội thoại trả lời cầu hỏi với nhiều kích thích phân biệt (2) khái quát hóa trong môi trường tự nhiên (3) phản hồi chức năng trong hoạt động phù hợp với lứa tuổi","12":"(1) Tăng số lượng Giới từ và Đại từ (2) Khái quát hóa và sử dụng chức năng","13":"(1) Tăng số lượng Tính từ và Trạng từ (2) Khái quát hóa và sử dụng chức năng","14":"(1) Tăng kho từ vựng Gán tên (2) Độ dài cụm từ và câu >4","15":"(1) Tăng kho từ vựng Gán tên (2) Khái quát hóa Gán tên mới học được mỗi ngày"},"NH":{"0":"(1) can thiệp ngay, biến âm thanh lời nói được chú ý bằng cách ghép với vật củng cố (2) xem xét rào cản và giải quyết","1":"(1) phản ứng thường xuyên với tên mình (2) chú ý đến tên người thân, thú cưng hay vật yêu thích","2":"(1) phân biệt mảng có 2 kích thích, lựa chọn vật yêu thích trong 2","3":"(1) tăng số lượng phân biệt gồm cả vật trung tính (2) khái quát hóa (3) thêm lệnh có hành động vận động cụ thể (4) tăng mảng chọn 3-4","4":"(1) tăng mảng chọn 4-6 (2) tăng sử dụng sách tranh (3) khái quát hóa nhiều ở môi trường tự nhiên","5":"(1) Trọng tâm giống Mốc 4 (2) thêm nội dung bộ phận cơ thể","6":"(1) Tăng số lượng (2) Khái quát hóa (3) tần suất diễn ra thường xuyên, tự nhiên trong cuộc sống hàng ngày (4) Mảng lựa chọn phức tạp hơn","7":"(1) Tăng số lượng (2) Khái quát hóa vốn từ đã có (3) Tăng độ phức tạp của hành động bằng cách đưa kích thích 2 thành phần (kích thích riêng lẻ có thể vẫn dùng khi học kỹ năng mới)","8":"(1) Tránh Gán thên và Nghe hiểu động từ hành động bằng hình ảnh lúc mới hình thành kỹ năng (sử dụng hình ảnh để khái quát hóa) (2) Tiếp tục tập trung vào kích thích 2 thành phần và phản ứng 2 thành phần","9":"(1) Tăng phản ứng với kích thích có 2-3 thành phần của ngôn ngữ như tính từ đặc điểm màu sắc, kích cỡ hay đại từ sở hữu (2) Khái quát hóa trong môi trường tự nhiên","10":"(1) Cân bằng với lĩnh vực ngôn ngữ khác như Yêu cầu, Gán tên, LRFFC và Hội thoại (2) Chuyển trọng tâm lĩnh vực khác khi mất cân bằng (3) Tăng quy mô kho từ vựng (tính từ, đại từ, giới từ...) (4) Khái quát hóa (5) Phản ứng trôi chảy (6) Phản ứng chức năng ở môi trường tự nhiên","11":"(1) Tăng số lượng tính từ màu sắc và hình dạng bổ trợ cho danh từ (2) Khái quát hóa trong hoạt động hàng ngày (3) Bắt đầu dạy giới từ Trong, Trên và Dưới bằng hoạt động cụ thể","12":"(1) Tăng số lượng giới từ trong mối tương quan với sự vật (danh từ) cụ thể (2) Tăng số lượng đại từ nhân xưng (3) Nhiều thử nghiệm và duy trì với đại từ sở hữu (4) Khái quát hóa và sử dụng chức năng","13":"(1) Tăng số lượng Tính từ liên quan trong mối tương quan giữa các sự vật (danh từ) cụ thể (2) Tăng số lượng Trạng từ liên quan đến đặc tính của động từ (3) Khái quát hóa và sử dụng chức năng","14":"(1) Tăng số lượng kích thích (chuỗi 3 thành phần) (2) Phản ứng chuỗi đúng chức năng (3) Khái quát hóa trong các môi trường, với nhiều người","15":"(1) Tăng khó từ vựng Nghe hiểu (2) Chuyển trọng tâm sang LRFFC"},"GM":{"0":"(1) kiểm tra thị lực (2) nếu thị lực ổn hãy đặt mục tiêu di chuyển hướng nhìn theo vật củng cố và củng cố ngay","1":"(1) mục tiêu phối hợp tay mắt (nhìn và với/cầm vật củng cố)","2":"(1) tăng số lượng hành vi phối hợp tay mắt (nhìn và với/cầm cả vật củng cố và trung tính)","3":"(1) tăng thời gian chú ý đến đồ dùng học liệu (2) tăng số lượng học liệu là vật trung tính","4":"(1) bắt đầu mục tiêu ghép mẫu 2 vật 3D giống hệt nhau (dùng vật củng cố)","5":"(1) tăng cơ hội ghép (2) tăng số lượng trong mảng (3) ghép mẫu trong môi trường tự nhiên (4) bắt đầu giới thiệu vật không giống hệt nhau","6":"(1) Tăng số lượng mẫu (2) Tăng kích thước và độ phức tạp của mảng lựa chọn (3) Ghép các vật thể không giống hệt nhau về màu sắc, kiểu dáng","7":"(1) Phân loại đồ vật theo nhiều tiêu chí khác nhau (FFC) (2) Bắt đầu so sánh giống và khác mẫu (không phải - mà là) (3) Kết hợp mẫu 2D và 3D trong các mảng lớn","8":"(1) Tiếp tục đa dạng mẫu so sánh giống và khác (2) Ghép nhiều thành phần của tạo nên mẫu tổng thể 2D hoặc 3D (3) Thiết lập Ghép mẫu mảng lớn 6-9, đồng thời trẻ phản ứng đúng với bất kỳ mẫu nào ngay lần thử đầu tiên","9":"(1) Ghép trong sách, cảnh, môi trường tự nhiên có tính chất khái quát hóa (2) Tăng Ghép mẫu có nhiều kích thích tương tự trong mảng lớn lộn xộn từ >10","10":"(1) Chuyển sang nhận thức trực quan phức tạp hơn như: thiết kế khối, mô hình, trình tự, quy luật đơn, hoạt động hoàn thành từng phần, các mảnh ghép, tô màu, ... (2) Không cần chú trọng nhiều vào ghép mẫu nữa, chuyển kỹ năng này sang Nghe hiểu ( làm mờ mẫu sau vài lần thử và chỉ còn kích thích lời nói)","11":"(1) chuyển sang các hình thức trừu tượng của nhận thức thị giác và các kỹ năng kết hợp như thiết kế khối, mảng ghép hình phức tạp (2) Khớp mẫu trong môi trường tự nhiên và hoạt động sự phù hợp với lứa tuổi","12":"(1) Tiếp tục chuyển sang các loại nhiệm vụ ghép trừu tượng hơn theo mẫu","13":"(1) Thực hiện mẫu và trình tự cao hơn, như sắp xếp theo thứ tự từ đầu đến cuối, từ bộ phận đến toàn thể (2) phân loại và nhóm các vật phẩm thuộc một danh mục cụ thể","14":"(1) Mở rộng xác định lớp/nhóm/loại mà vật phẩm đó thuộc về (2) Kỹ năng ghép mẫu chuỗi trình tự 2-3 bước (3) Khái quát hóa","15":"(1) tiếp tục tập trung vào các mẫu, thiết kế, trình tự phức tạp hơn (nội dung có thể liên quan đến tiền học đường)"},"CDL":{"0":"(1) can thiệp ngay, tạo hứng thú với đồ vật/chơi thông qua vật củng cố khác (vd: đồ ăn)","1":"(1) tăng hành vi chơi với nhiều đồ vật (mới lạ, hấp dẫn), đồng thời củng cố xã hội","2":"(1) tăng tần suất lặp lại hành vi chơi với các đồ chơi có tác dụng cụ thể (chơi đúng tính chất đồ chơi)","3":"(1) tăng hành vi chơi đúng tính chất/chức năng với nhiều đồ vật mới lạ, đồng thời củng cố xã hội","4":"(1) chơi đồ chơi nhân quả (2) chơi trò chơi vận động thể chất","5":"(1) tăng độ phức tạp của các trò chơi (2) kéo dài thời gian chơi với một/một bộ đồ chơi cụ thể","6":"(1) Tăng số lượng đồ chơi mới lại và đa dạng (2) Không cần nhắc và củng cố vật chất nào khác ngoài củng cố xã hội","7":"(2) Tăng tần suất hành vi chơi chức năng với nhiều đối tượng (2) Dạy kỹ năng chơi đồ chơi nhiều bộ phận, hoạt động chơi 2-3 bước","8":"(1) Tăng tần suất hành vi chơi biểu tượng thông qua các vật dụng hang ngày trong môi trường tự nhiên (2) Bắt đầu các hoạt động chơi giả vờ có chủ đề","9":"(1) Phát triển các trò chơi thể chất phù hợp với tuổi (2) Tăng tần suất hành vi chơi tưởng tượng xã hội có sự củng cố xã hội của người lớn (nếu cần)","10":"(1) Kéo dài thời gian chơi vào một món đồ hay một hoạt động cụ thể (2) Phát triển chơi lắp ráp tạo thành tổng thể hoàn chỉnh (3) Tăng cường sự đa dạng hoạt động chơi tưởng tượng","11":"(1) Tăng các hoạt động chơi giả vờ phù hợp với lứa tuổi","12":"(1) Tăng hoạt động chơi vận động có kết quả cụ thể phù hợp với tuổi","13":"(1) Kéo dài thời gian chơi vào một hoạt động chơi cụ thể (2) Khái quát hóa hành vi chơi","14":"(1) Tăng thời gian chơi độc lập vào hoạt động chơi có ý nghĩa và phù hợp với lứa tuổi (2) Cân bằng cột mốc chơi độc lập với chơi xã hội","15":"(1) Tăng thêm nhiều hoạt động độc lập liên quan đến kỹ năng tiền học đường"},"CXH":{"0":"(1) Xem xét rào cản và giải quyết (2) sử dụng các chiến lược để người lớn trở thành nguồn củng cố càng sớm càng tốt","1":"(1) tiếp tục chiến lược người lớn là nguồn củng cố (2) giảm các kích thích ảnh hưởng đến trẻ (âm lượng, giọng điệu, biểu cảm…)","2":"(1) chấp nhận tương tác thể chất với người lớn (2) chấp nhận ở gần bạn/nhóm bạn","3":"(1) tiếp xúc thể chất với bạn bè (2) hành vi bắt chước bạn cùng lứa","4":"(1) tương tác cụ thể với bạn bè (yêu cầu và thực hiện yêu cầu, bắt chước nhau, chơi theo lượt) (2) giảm dần lời nhắc","5":"(1) tương tác cụ thể với bạn bè (cùng làm, cùng chơi) (2) thêm trao đổi ngôn ngữ bằng lời khi chơi","6":"(1) Yêu cầu và đáp lại yêu cầu với bạn (chọn yêu cầu chứa đựng củng cố hoặc loại bỏ khó chịu) được dạy trong môi trường giả định (2) Làm mờ nhắc nhở","7":"(1) Tự phát yêu cầu và chú ý để phản hồi yêu cầu của bạn (2) Dạy luân phiên và chia sẻ trong bối cảnh vui chơi","8":"(1) Hợp tác: bắt chước và lặp lại hành vi chơi của bạn (2) Tăng số lượng yêu cầu và phản hồi yêu cầu, luân phiên và chia sẻ (3) Bắt đầu hướng dẫn hội thoại đơn giản (4) Giảm đến không có lời nhắc của người lớn","9":"(1) Hình thành tình bạn (bạn giữ vai trò là tác nhân củng cố) (2) Hướng dẫn mời/rủ bạn bè tham gia vào hoạt động chơi (3) Thiết lập chơi song song và phối hợp trong các trò chơi","10":"(1) Khuyến khích tương tác bằng lời nói thường xuyên khi chơi với bạn: Dạy mô tả/bình luận trong hoạt động chơi làm tiền đề cho kể chuyện giai đoạn sau (2) Bắt đầu khởi xướng và hồi đáp hội thoại theo 1 chủ đề với bạn (3) Hợp tác với bạn bè khi chơi","11":"(1) trọng tâm nên là cung cấp các cơ hội hàng ngày để khái quát hóa hành vi hợp tác (2) mở rộng các hành vi thân thiện với bạn bè trong hoạt động phù hợp với tuổi","12":"(1) Có nhiều cơ hội để thử nghiệm và duy trì Yêu cầu bạn bè (2) Phản ứng đúng và kịp thời với các yêu cầu của bạn bè bằng ngôn ngữ và phi ngôn ngữ","13":"(1) khái quát hóa và mở rộng tương tác này bằng cách cung cấp các bối cảnh và cơ hội đa dạng có phản hồi Hội thoại với các bạn đồng trang lứa","14":"(1) Thúc đẩy hoạt động chơi sáng tạo với bạn bè, có trao đổi ngôn ngữ trong khi chơi","15":"(1) Mở rộng và thúc đẩy hoạt động chơi nhóm: có tương tác qua lại và Hội thoại theo chủ đề chơi"},"BC":{"0":"(1) nỗ lực can thiệp ngay lập tức, sử dụng nhắc toàn phần, lựa chọn kỹ lưỡng kích thích và củng cố","1":"(1) tăng số lượng hành vi bắt chước vận động thô","2":"(1) bắt đầu thêm hành vi bắt chước sử dụng cử chỉ tay (tạo đà cho học ngôn ngữ ký hiệu nếu trẻ không có khả năng phát âm)","3":"(1) tăng hành vi bắt chước vận động thô và cử chỉ tay (2) bắt chước hành vi mới trong lần thử đầu tiên (3) không nhắc (4) bắt chước bạn cùng lứa","4":"(1) trọng tâm giống mốc 3 nhưng tăng số lượng và tần suất","5":"(1) bắt chước sử dụng đúng chức năng đồ vật (2) bắt chước 2 thành phần (3) bắt chước tự phát và song song","6":"(1) Khuyến khích bắt chước tự phát (2) Tăng số lượng hành vi bắt chước vận động (3) Bắt chước hành động chức năng với đồ vật cần tinh tế, phức tạp hơn (4) Phát triển cân bằng với Phát âm","7":"(1) Bắt chước tự phát thường xuyên (hiểu được nguồn củng cố từ hành vi bắt chước) (2) Bắt chước hành vi mới của người lớn (3) Bắt chước tự nhiên trong bài hát, trò chơi lứa tuổi (4) Làm mờ lời nhắc","8":"(1) Tăng sự đa dạng và chuỗi bắt chước 2-3 hành vi (2) Bắt chước song song (tập trung đa giác quan) (3) Môi trường tự nhiên và có chức năng (bài hát và trò chơi vận động)","9":"(1) ự phát bắt chước ngay từ lần thử nghiệm đầu tiên (2) Khái quát hóa kỹ năng bắt chước trong môi trường tự nhiên (3) Phát triển kho hành vi bắt chước tổng quát","10":"(1) Trẻ đạt được hành vi tổng quát kỹ năng bắt chước, mục tiêu dạy bắt chước không cần thiết dạy trong môi trường thiết lập nữa mà phát triển bắt chước chức năng trong môi trường tự nhiên"},"PA":{"0":"(1) nỗ lực can thiệp ngay lập tức (2) sử dụng giao tiếp tăng cường/thay thế và các kỹ thuật kích thích tạo âm lời nói","1":"(1) củng cố ngay lập tức các âm của trẻ (2) luyện tập âm đã có","2":"(1) tăng số lượng âm phát ra (2) tăng tần suất phát âm hàng ngày","3":"(1) trọng tâm giống Mốc 2 (2) xem tính cân bằng với Yêu cầu và Gán tên, nếu thấp hơn thì can thiệp sâu rộng, nếu cao hơn thì sử dụng Phát âm để dạy kỹ năng khác","4":"(1) tăng số lượng phát âm (2) tăng tần suất (3) khái quát hóa với người và bối cảnh","5":"(1) bắt đầu với mục tiêu đặc tính của ngữ âm (trọng âm, ngữ điệu)","6":"(1) Phát âm đa âm tiết (2) Sử dụng được phát âm vào các lĩnh vực khác như Yêu cầu, Gán tên, Hội thoại","7":"(1) Không cần lên mục tiêu can thiệp cụ thể nữa mà Kết hợp với các kỹ năng ngôn ngữ khác (2) Phát hiện lỗi phát âm cụ thể sớm","8":"(1) Trẻ đạt được năng lực bắt chước/lặp lại từ mới lạ (2) Lỗi phát âm nếu có cần được phân tích cẩn thận bởi nhà trị liệu ngôn ngữ","9":"(1) Hình thành phản xạ âm thanh tốt hơn (chính xác hơn) trong các mẫu phản hồi ở các lĩnh vực ngôn ngữ","10":"(1) Trẻ đạt được hành vi tổng quát kỹ năng phản xạ âm thanh (nói đúng, xấp xỉ đúng với các từ và cụm từ ngắn) nên Không cần đặt ra mục tiêu cụ thể"},"LN":{"0":"(1) tăng cường cơ phát âm bằng cách tăng tần suất phát âm hàng ngày","1":"(1) tăng biến thể của âm thanh phát ra (ngữ điệu, âm lượng, cao độ, nhịp điệu)","2":"(1) trọng tâm giống mốc 1 (2) tạo ra các âm mới","3":"(1) phát triển cận từ dựa vào sự hòa trộn của các âm thanh","4":"(1) tăng cường âm bập bẹ ở mức độ thường xuyên (2) đưa âm thanh vào Yêu cầu, Gán tên và bắt chước Phát âm","5":"(1) chuyển hành vi lời nói tự phát vào Yêu cầu, Gán tên (cả âm cũ và mới tự phát) (2) phát triển trong bài hát và cụm từ vui nhộn"},"FFC":{"6":"(1) Làm quen với kiểu phản hồi FFC mà không cần gọi tên, (chủ yêu dựa trên danh từ - động từ trong kho từ vựng của trẻ)","7":"(1) Mở rộng vốn từ vựng FFC ra ngoài vật phẩm củng cố (2) Bắt đầu giới thiệu câu hỏi Wh (gì, đâu, ai, cái nào?) (3) Khái quát hóa các mục đã biết và người (4) Thay đổi ngữ điệu (5) Tăng kích thước mảng","8":"(1) Chuyển đổi tốt hơn từ dạng điền vào chỗ trống sang trả lời câu hỏi:Wh? (2) Kích thích khác nhau cho cùng một phản ứng về nội dung (3) Khái quát trong môi trường tự nhiên","9":"(1) Đào tạo mẫu nhiều lần và trên nhiều mẫu (2) Khái quát hóa phản ứng trong môi trường tự nhiên (3) Phản ứng trôi chảy và nhanh (4) Phản ứng tự phát (5) Bắt đầu chuyển sang dạy Hội thoại (phản ứng ngôn ngữ có lời thay cho phi ngôn ngữ)","10":"(1) Mảng chứa nhiều kích thích tương tự nhau (2) Kích thích lời nói nhiều thành phần (2-3 thành phần) (3) Bắt đầu sử dụng LRFFC với sự việc trong quá khứ và tương lai (4) Khái quát hóa trong môi trường tự nhiên","11":"(1) tập trung vào các mảng phức tạp hơn từ sách hình ảnh có chứa các kích thích tương tự, cảnh phức tạp, câu chuyện, chuỗi, sự kiện xã hội hoặc địa điểm mới (2) tiếp tục tăng độ phức tạp kích thích bằng lời dựa trên kho từ vựng của trẻ về tính từ","12":"(1) tăng kích thích bằng lời bao gồm nhiều thành phần hỗn hợp danh-động - tính - trạng - giới - đại từ (2) tập trung nhiều hơn vào việc chuyển các hoạt động LRFFC sang các thử nghiệm Hội thoại qua vòng xoay các câu hỏi Wh","13":"(1) trình bày các sự vật và hoạt động khi những sự vật và hoạt động đó không còn nữa (2) khải quát trong môi trường tự nhiên (3) tăng số lượng xoay vòng các câu hỏi Wh","14":"(1) dạy khái niệm phủ định (không phải là, không thể là, không có …)","15":"(1) Chuyển trọng tâm sang Hội thoại"},"HT":{"6":"(1) Đa dạng các kích thích lời nói để trẻ có phản ứng phù hợp (2) Tần suất thử nghiệm điền từ diễn ra hàng ngày (3) Khái quát hóa môi trường và người","7":"(1) Bắt đầu phản ứng bằng lời với các câu hỏi What và Who? (2) Thử nghiệm kích thích lời nói nhiều thành phần với phản ứng điền từ (3) Rút ngắn thời gian phản hồi","8":"(1) Chuyển đổi từ dạng điền vào chỗ trống sang trả lời câu hỏi Wh (Gì, Ai, ở đâu) (2) Thử nghiệm VB hỗn hợp để phát triển hội thoại (3) Khái quát trong môi trường tự nhiên, nhiều người nói với các ngữ điệu và bối cảnh khác nhau","9":"(1) Mở rộng hội thoại theo cách phát triển VB hỗn hợp với các chức năng ngôn ngữ đã làm chủ (2) Khái quát hóa phân biệt kích thích lời nói và phản hồi phù hợp với đa dạng vật phẩm/chủ đề","10":"(1) Phát triển ngôn ngữ lời nói nhiều thành phần, cấu trúc câu dài 4-8 từ (2) Nói về vật/sự kiện không xuất hiện trong môi trường giao tiếp (3) Phân biệt câu hỏi có hai thành phần và có phản ứng phù hợp (4) Trả lời các câu hỏi chức năng vật phẩm","11":"(1) mở rộng sự phức tạp của các kích thích (kích thích bằng lời nhiều thành phần) (2) mở rộng sự phức tạp của phản ứng (có nhiều thành phần) (3) Tăng số lượng phản ứng hội thoại","12":"(1) Mở rộng nội dung hội thoại, không tập trung quá vào cấu trúc ngữ pháp","13":"(1) khái quát hóa nguồn kích thích (2) khái quát hóa phản ứng ( linh hoạt phản ứng, tránh mắc lỗi lặp đi lặp lại về một chủ đề) (3) hội thoại có chức năng","14":"(1) trả lời chính xác nhiều câu hỏi Wh về một chủ đề duy nhất (câu hỏi chứa nhiều thành phần) (2) nội dung hội thoại về quá khứ và tương lai","15":"(1) Phát triển Hội thoại về chủ đề (thêm nội dung mới), tần suất, thời lượng và đối tượng (2) phản ứng trôi chảy"},"KNN":{"6":"(1) Tăng thời gian ngồi trong nhóm ở các nội dung hoạt động có tính chất củng cố (2) Thiết lập quyền kiểm soát hướng dẫn của người lớn (3) Tuân thủ dần các thói quen lớp (vị trí, hoạt động khác nhau)","7":"(1) Tuân thủ thêm thói quen khác ở lớp học: Chuyển đổi hoạt động, các loại hoạt động và giờ học nhóm (2) Thời gian kéo dài hơn (3) Giảm nhắc nhở trực tiếp","8":"(1) Ngồi học trong nhóm lớn hơn 3 mà không có hành vi tiêu cực (2) Có chú ý đến giáo viên, tài liệu học tập (3) Đưa ra vài phản hồi phù hợp khi được yêu cầu","9":"(1) Tuân thủ chắc chắn định dạng học nhóm: Chú ý giáo viên, tài liệu và phản hồi (dựa trên thứ trẻ đã biết) (2) Tăng dần số lượng trẻ trong nhóm (3) Thêm các quy định hành vi giờ học nhóm (4) Bắt đầu chú ý đến bạn trong nhóm lúc phù hợp","10":"(1) Tiếp thu hành vi mới từ học nhóm (2) Làm quen với kiểu “kích thích phân biệt Nhóm” (không nêu cụ thể một trẻ nào) (3) Tăng quy mô nhóm","11":"(1) Thêm các hoạt động mục tiêu cho thói quen lớp học","12":"(1) trọng tâm là các hoạt động làm việc độc lập hơn trong nhóm (2) thêm các kỹ năng mới được học theo phương pháp hướng dẫn nhóm","13":"(1) tăng thời gian hoạt động độc lập trong nhóm mà không cần nhắc nhở (2) đa dạng hoạt động phù hợp theo tuổi","14":"(1) tăng số lượng kích thích và phản hồi theo phương pháp học nhóm (2) kích thích phức tạp hơn và phản hồi nhiều thành phần","15":"(1) giảm thiểu thời gian đào tạo 1:1, tăng thời gian đào tạo theo phương pháp nhóm"},"NP":{"6":"(1) Tăng vốn từ vựng (tập trung vào danh từ và động từ, từ ngắn, tránh nhiều từ gần giống nhau)","7":"(1) Cân bằng giữa Nghe hiểu và Gán tên, giữa các từ được nói ra với các từ được hiểu theo hình thức phản hồi của người nghe","8":"(1) Tăng phản hồi có độ dài MLU là 2 và 3 với nội dung đa dạng hơn","9":"(1) Thay đổi tông giọng (vd: to nhỏ), ngữ điệu khi nói phù hợp với bối cảnh (2) Khái quát hóa với người và bối cảnh","10":"(1) Tiếp tục tăng vốn từ vựng trong tất cả các hoạt động ngôn ngữ","11":"(1) Tăng biến tố số lượng (một - nhiều) và sở hữu (của, thuộc về) cho danh từ và đại từ (2) Phát âm chính xác các biến tố danh từ và đại từ trong tiếng Anh (s, es, 's)","12":"(1) Tăng biến tố cho động từ ở thì quá khứ, hiện tại và tương lai (đã, đang và sẽ) (2) Phát âm chính xác các biến tố động từ trong tiếng Anh","13":"(1) khái quát hóa cách sử dụng các cụm danh từ (danh từ chính và có tính từ, mạo từ, từ chỉ định bổ nghĩa) có tính chức năng (2) bắt đầu chuyển sang sử dụng cụm động từ trong Yêu cầu, Gán tên, Hội thoại","14":"(1) khái quát hóa cách sử dụng các cụm động từ (động từ chính và có trạng từ, đại từ, giới từ bổ nghĩa) có tính chức năng (2) bắt đầu chuyển sang kết nối cụm danh từ và cụm động từ theo chức năng","15":"(1) tăng số lượng các câu kết nối giữa cụm danh từ và cụm động từ (2) khái quát hóa và theo chức năng (3) Tăng MLU"},"DOC":{"11":"(1) Tăng số lượng và tần suất, thời gian nhằm củng cố hành vi xem sách (2) Học tên và phát âm chữ cái thông qua các kỹ năng Ghép mẫu, Nghe hiểu, Gán tên) (3) Phân biệt chữ cái thường và hoa","12":"(1) khái quát hóa các phông chữ và ngữ cảnh khác nhau (2) Nhận diện chữ viết tên trẻ và người thân thiết","13":"(1) Mở rộng đặt tên cho các chữ cái","14":"(1) Mở rộng đánh vần tên người thân, thú cưng, sự vật trẻ thích (2) Bắt đầu ghép tên (từ) với hình ảnh","15":"(1) Mở rộng ghép từ với hình ảnh (2) Đọc từ hành động và thực hiện theo"},"VIET":{"11":"(1) Tăng khả năng kiểm soát công cụ viết trên cấu hình (2) Cải thiện kỹ năng vận động tinh thông qua hoạt động tô màu, vẽ, đồ …","12":"(1) Tăng khả năng kiểm soát được nhiều công cụ viết khác nhau (2) Tăng số lượng các bài tập tô theo đường nét, chữ số và chữ cái","13":"(1) Chép các chữ số, chữ cái viết hoa và viết thường (2) Tô, Vẽ các bức tranh có chủ đề và nhiều đường nét","14":"(1) Sao chép toàn bộ các từ mà trẻ thấy vui (từ về những thứ trẻ quan tâm, thích thú) (2) Thực hiện các trò chơi mê cung, điền số, nối điểm …","15":"(1) Sao chép chữ cái ở kích cỡ nhỏ hơn (2) Giữ được thiết lập tương đối trên dòng kẻ"},"TOAN":{"11":"(1) Sử dụng các kỹ năng Nghe hiểu và Ghép mẫu để chuyển sang dạy các số >5 (2) khái quát hóa các phông chữ, màu sắc, hình dạng số khác nhau (3) thực hành đếm thuộc lòng và điền vào các số còn thiếu","12":"(1) đếm các vật phẩm có sự tương ứng phạm vi 5 (2) đếm thuộc lòng đến 10 hoặc hơn (3) thêm các hoạt động phép đo đơn giản (ví dụ: lớn và nhỏ), hình học đơn giản (ví dụ: hình tròn, hình vuông, ), tập hợp (ví dụ: giới từ trong) và phân loại (ví dụ: sắp xếp)","13":"(1) tăng số lượng mảng (2) tăng phạm vi kích thích lớn hơn 5 (3) thêm các hoạt động phép đo phức tạp hơn (ví dụ: đầy và vơi), vị trí (ví dụ: đầu tiên và cuối cùng, dưới cùng và trên cùng), và mốc thời gian (ví dụ: hôm qua, hôm nay, ngày mai)","14":"(1) Ghép số với số lượng cụ thể trong phạm vi 5 (2) ghép tương quan số lượng bằng nhau (3) giới thiệu nhiều hơn và ít hơn","15":"(1) Phát triển nhiều khía cạnh toán học phù hợp với độ tuổi (vd: Ghép số với số lượng cụ thể, tìm quy luật, so sánh đa dạng hơn, mê cung, thời gian, thêm vào và bớt ra…)"}};
